INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('7eccacf5-ef7b-4dab-b588-66dffd6d8e35', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "83182169-62cb-4e26-8481-18695682cea9", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "1d7dc792-1ad3-434a-8b43-5701edddfb43", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "6b039f03-d6af-4b0e-9cca-276558791b9f", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "1d24744c-91fb-4a0a-8267-452285357e89", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "6de0ea14-4f1e-47b7-b39a-bc403904aa23", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "bad84e6a-34e0-491a-bcc3-d62566a3295e", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "633d7df0-42bb-408b-a1af-3d5ba9bc08fa", "text": "Igaz", "isCorrect": true}, {"id": "d5c4b22c-dca4-4d73-92c3-31b6d28c867b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f741dec-b00c-40ac-88b2-b9b19ef5d018", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "a824bf58-af0c-47c2-8baa-b7a439116803", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "8c45f21b-46d6-497b-97bb-2ef7a8869bdd", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "ca45fe97-e748-4c19-9ac0-a7c2e277e04f", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "2c138cd5-2a38-4091-b7b0-6499dbbeab51", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "c0162c39-3497-4367-b1b4-95253ca3ab68", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "e6d3cae4-4a71-4b09-8bbe-2a16deb185e0", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "e0f7922a-27e8-469f-857a-7c3e17317ffc", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "33118908-a4a2-444e-8f36-043db6e5c068", "text": "Igaz", "isCorrect": true}, {"id": "ab48a81c-fb82-48a6-8aaa-df7aafb401d7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fb1b9027-0807-408a-9174-1aeb7ec2d185", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW()),
('dee68c24-88a4-4696-a397-c1c4deedb937', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "dc1aa622-2c63-41b6-9518-7053ad3a0262", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "c87e4b24-943e-4391-b37f-4aa91737c8fa", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "a4f5046b-6cd2-4cc0-b008-2b55b2e9d8b2", "text": "Parabola", "isCorrect": false}, {"id": "eaafe429-ec3b-495b-b9b9-ce5760959f49", "text": "Körvonal", "isCorrect": false}, {"id": "78c9d3de-8435-4545-902d-6d016752c5cb", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "3e118d6a-6fa6-460d-ba4e-92d344b3f1f9", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "dcd65455-d6dc-43d0-b89b-09e22871c6af", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "aedf8d6d-d3f6-464c-b909-431193b32d99", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8eeeaa9f-c0fc-4849-897d-6269c4ed129f", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "f3888b8e-9bf0-4779-8621-a466b706bf8d", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "80cd5a09-0a76-4db1-b161-3735e4194c97", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "ce67448d-00d4-4f4f-8331-35774d71cde2", "text": "Igaz", "isCorrect": true}, {"id": "a25bda8e-552c-4d80-94a2-9278f98c00ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e19cdf27-bb73-4551-b3ed-591d7a3e34f3", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "73dcca98-e262-4c7f-8ca0-af6b97ea1e19", "text": "Igaz", "isCorrect": true}, {"id": "1a3aacb5-84f2-43b9-a2c5-082532143148", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "283bf4c9-1df8-408e-b4eb-f61b4f1060b1", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "f2abda2d-da94-41b3-9fc8-682bc92b8f11", "text": "Igaz", "isCorrect": true}, {"id": "f201e557-ee91-40aa-b669-777bd631f047", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('b38d3ac6-583c-48e2-968d-53d19d569e15', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "41478cc3-8cfb-4821-b746-71583ec79dc2", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "9dfa2e83-b42a-4d9f-9fed-5525e17f9c28", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "88f2573e-2484-45a5-a5f5-fcb6a120d7ef", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "9ac86621-1fb9-424f-a58f-3216fc07e28c", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "cd26f828-7141-4f13-9218-037720344da5", "text": "Igaz", "isCorrect": true}, {"id": "c285601f-192b-43c3-93ee-50e823ddd47f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "954ad3c1-51e0-47cc-a80c-9ca60f0250cc", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "1cb254e2-c51e-4d40-89d0-21291112d570", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "351c43dd-0d6d-4886-b74b-82a045b8da21", "text": "Igaz", "isCorrect": true}, {"id": "db44b502-b7ef-46b2-9550-400f658fad80", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9e96fba0-055d-4754-ade3-c26fe6d8d16b", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('69cada4c-8e88-472b-a68f-fceceb5bf77c', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "214552a5-cccd-4188-96e2-19563b3554dd", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "28d4aba1-7c1b-4f0d-9093-a6a2781051c2", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "fada8f62-8d06-4b83-8bc4-d2dc83d02c80", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "3624b79d-e32d-4291-b772-463b0fed685e", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "13e899ab-88e7-4d78-986c-4c27797e4c73", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "1eaa91e0-1e7a-4a37-a377-67be97866798", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "f0070842-9884-4620-a6f8-4cc8d9a5ba73", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "2e791ce3-7442-4214-bd57-cfcab2192245", "text": "Igaz", "isCorrect": true}, {"id": "aa2a823d-8791-44b5-a794-610bab93fbeb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ea983231-053a-4c01-af06-c560632efa4f", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "6c2cad04-f934-45e7-93bd-ef795d52dca1", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "7cb329fe-3894-4208-8cb4-d310f4ccacaa", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "bfd9f7e4-5e03-4617-b859-5f03a26150b0", "text": "Igaz", "isCorrect": true}, {"id": "d4ef77fe-585e-4c10-b3f7-5f09765a89e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e638ae21-0ad8-4dd7-824b-55ed0f39d15e", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "bbc439d8-843c-4899-9323-fc03da9d186e", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "a4041b73-4413-4291-af5f-ecdac42d29f1", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "e577f7f3-b83f-4dbb-ad42-11e877061aa0", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "fa3538ba-442d-4cc0-86e4-16293e9d0fe8", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('03673fef-7130-4ea9-ae1c-97c58e9496c1', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b5d3bcc0-e77f-4e21-90e0-44139d488062", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "daae8049-90fe-4497-85d2-43d4ace72acc", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "aa34ddd0-c23a-428e-8686-0399ea720d1e", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "8a567597-17ad-4946-902e-dae8fac7af29", "text": "Igaz", "isCorrect": true}, {"id": "bb1e3b95-5b81-434e-b107-de46b64db61d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6f8fdf63-611b-47f2-bba4-fc93faee95d6", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "ffd51794-2b94-488e-8d2e-4b8059435cba", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "c197501a-bf7b-45fd-bb28-ac60d71c73c5", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "60de0f49-00a5-41d8-bb74-c15ad2bca044", "text": "5, 25, 125", "isCorrect": false}, {"id": "b4d86757-3c39-4f4a-9f23-feb5d99eb05c", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "e28c25be-6a65-4000-aa06-28b72cad32eb", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "cb198c79-754b-4ebb-bde3-a7ea675d7af5", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "1433ff55-2bda-49b9-92e1-b2de510ce5e9", "text": "Igaz", "isCorrect": true}, {"id": "df2153b0-1967-42b8-9e8d-fa8736fc1126", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "794f25de-e68a-4946-943c-cebdb40fd321", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('087498e3-0eb9-4a30-8292-74503db59583', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "47bb5b48-c6fe-4c3b-a83c-bb0c393705b2", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "eeaa3215-33ae-4879-b1ae-ca9d587d9d7b", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "e6774a99-9a52-41db-9d10-271b7f0a6062", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "ed8e5f62-613e-40b1-b1cb-f3b19a37f65c", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "fa6e92cf-3804-4116-8aba-cd92d920315c", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "36c9fd94-2154-430b-a58c-b9fdd2db602d", "text": "Igaz", "isCorrect": true}, {"id": "2eb27baf-4821-43ab-a16b-7db80ca0a740", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "23baf82e-a508-490d-8a2c-7fb808998352", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "1199563c-b049-4552-bcfa-e67b74eeb82b", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "ecaf0d2a-1f3b-4e9b-8ed1-c78487c1dc31", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "d603cb6c-157e-46a2-9430-65a47464456b", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "f8da1c50-e0a7-41b5-83c2-d05d4f8dc5ec", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "d2453074-c426-4f01-9200-ba8ccd3d9cff", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "e8dfb988-890b-4564-ace9-ff366d9c8d60", "text": "Igaz", "isCorrect": true}, {"id": "9bf885f1-8906-4421-9b59-f07b31ffdad0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('eca87480-88e7-4490-b7a7-5e501edae0a7', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bc65b14e-8dd2-4e3a-966d-e6d14e91dd51", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "b1ee9672-02e7-4092-82a6-a11ddb7e6d2a", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "72a8283f-a4d1-4d63-a9f1-67825aa790de", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "7a3e21be-e93c-4c43-93d9-f53c5f962d50", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "ec69935e-ea38-440f-969e-6dde22a1b830", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "ae02f5e9-a9fe-4e02-8424-04e5c5a1c51f", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "ad14cd03-ca2c-4e0f-bfd4-f3c8f8f7d45f", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "ebf56f1b-66d6-4e04-8d8b-4161ab78e80c", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "2b664c15-ba23-4e08-af6a-73d337265918", "text": "Igaz", "isCorrect": true}, {"id": "f9a5cc93-cfcd-419b-af3c-495c513a1b03", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f70959c9-d111-42f5-9d64-eac15d1ce885", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "176b2731-852d-45a7-bca9-0a607f19a6c6", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "ec180375-6dae-47d8-9503-59e1012a8911", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()),
('5ab0d4df-0cdb-412d-892d-57db6a3d9455', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "747bb026-4e5f-4cd8-9175-a7ec91943ac0", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "cb9f2993-7d91-49c3-b0fb-c0481ba1d32f", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "19e84f8c-9a2e-4bc5-a966-386c212de7f1", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "f19b7ee0-1d97-489d-abb9-c9e91361c60e", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "3bacfb83-34bf-4c23-a2a1-76a94693cdd5", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "71be21c1-4ad6-4fd6-acde-52651e4e43ba", "text": "Igaz", "isCorrect": true}, {"id": "6df46fb3-5e8d-4bfb-af1a-076030e106ed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ae09270-4974-4bdc-9a77-c87a15d32082", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "25d275b2-a97f-40fb-8aad-8c644424f5b2", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "07d04138-39fb-4b3f-af58-7607d1abb74e", "text": "Igaz", "isCorrect": true}, {"id": "665f3fe6-dba1-44d4-b985-d8c66f8d7589", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('d728425a-0b3a-4325-be53-c19886b1f829', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6c04f9e5-94a0-4cf6-a9cf-64fcfcd8ce6b", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "5b305f7a-564f-4942-b7bf-03b327f9a455", "text": "1 : 3", "isCorrect": true}, {"id": "1d756573-85fe-4bca-9ed1-9f186cdf0447", "text": "1 : 2", "isCorrect": false}, {"id": "fa92ca17-8de6-4570-8034-98e867696830", "text": "3 : 1", "isCorrect": false}, {"id": "d7bbcbc6-30c5-460f-9d21-9648bb9dbf19", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "a3f3524c-ffa4-4e04-8f52-62c85b13c846", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "8a3f3de9-207c-407a-89b1-b4a222cb3887", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "c6cd6757-3681-4869-b999-f210fd75a23e", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "b8d6d0c8-391b-4afe-ac58-d15cd48b5a74", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "187a7575-df37-4ff7-a171-bf70ec3a5f3e", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "d173aa9d-5ad0-4fb6-b3fd-70dba6b636b6", "text": "Igaz", "isCorrect": true}, {"id": "e45b0a7a-8d27-4810-84b1-053a07b7d040", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00bd80e4-7da5-4100-84bf-88fab753edac", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c808e01e-c190-4b97-9972-7acee6e3ffa5", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "eb60f3e7-3d76-4ada-a3b2-d07d93988c9a", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "5889522a-c920-4eef-b3f4-4970525c1835", "text": "Igaz", "isCorrect": true}, {"id": "bad1ecc7-cc41-4af0-b914-346725ce2eff", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "637c3a3e-7394-4b2e-81da-0ceaee9c85b4", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()),
('89e4a7fb-a464-494b-bcf4-571d22f9c068', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8b40957b-2869-460e-8569-deef7c451b02", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "f2436556-4434-4dab-8a0a-712f98478dc9", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "f2a98613-2a89-4ac8-abb0-7beb21b186cb", "text": "1 : 3", "isCorrect": true}, {"id": "d63c2057-1525-421e-9327-dd3414c40b02", "text": "1 : 5", "isCorrect": false}, {"id": "58c234cc-f234-40e7-aeff-6ae2eb40649f", "text": "3 : 1", "isCorrect": false}, {"id": "495c36f8-15ba-4eed-b5b1-38747825cbd7", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "1147841d-b0ba-42b9-8056-582e47bb55be", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "4a6cb058-226e-47c3-a48b-25e0f5bb8e5e", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "bd8f7f95-9e45-42d6-a580-747e4a692124", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "7fbcbc14-2b5c-4b76-bae0-72291726105c", "text": "Igaz", "isCorrect": true}, {"id": "4153cf7a-42ea-4be6-a759-40db25f96f40", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "374d16b4-f106-4669-b35e-54c7f732a94e", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "7ef1a29c-6787-46f0-b891-05c222a94703", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "8de73ed3-7c17-464c-8c00-d09a081e615a", "text": "Igaz", "isCorrect": true}, {"id": "b31caff7-716c-4016-b735-135d072ef4d3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('ea11fb83-a1f3-4b7e-ab39-7cd6f66a6033', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "31f1ffd5-7349-4426-a964-bfc5e1737982", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "ded4fdbe-2e69-4c8f-bd0d-3852521ba563", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "dc4c7859-f874-41a4-8277-135e39ee5cc2", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "e81315c8-8d63-42fb-b6e0-e64be45c5c87", "text": "100 egészet", "isCorrect": false}, {"id": "4a28dc23-fad9-48fc-9d24-b317d69b88d6", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "bd5f710b-e3b5-4ee3-bd0d-5bb35531f4a4", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "316e32cb-83b6-456d-b15e-95bf8364dcdb", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "5cc7beca-551f-4762-9714-984a1abaedf2", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "b84cd37d-2a13-4e71-b863-a89a7feb9f80", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "1b122b6e-892a-4168-bebd-a6fd3c84c14e", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "66703901-4a0b-4157-b053-ba6840014024", "text": "Igaz", "isCorrect": true}, {"id": "35ef5e4d-2291-4545-8c28-5288f021523c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03c826d0-b082-4c41-b690-298aea8bd828", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "b9400c37-16c7-424d-ba47-8a49abdda849", "text": "Igaz", "isCorrect": true}, {"id": "0109d49c-4ee2-4251-b006-f3b3dbcea018", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('54fad952-edbe-40e6-b0ee-e5f32e46caac', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4f527cc2-8bbd-4f8e-a97a-051e80a552cc", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "f0382bab-a728-4126-8448-4f3c7d91e20c", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "ef666a51-69bc-4172-bc94-08e535f2cc8c", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4cfa65d7-424f-43a5-91f1-cb2a999f6808", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "da254b9d-8416-4f8b-9b0e-b2a39d29baa0", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "5b879ae5-4e63-4c07-a7cf-8ab4bb04e09c", "text": "Igaz", "isCorrect": true}, {"id": "156aaf34-6005-4bd2-a6f4-a18298e871a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc713d3f-f465-4f61-8385-8da1455d98e9", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "cbe0a264-881e-45d3-a0a9-ce3e25983533", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW()),
('4ae20ca7-2474-4e25-a88d-b79aec89332f', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "557dd6a3-93cb-45fe-ae96-e0bc425e8979", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "c36d2b59-22c4-40f4-b694-0d732774ce26", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "af0300bd-7c8b-4950-b22b-49e9c658376b", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "0469aa62-a6a8-41cb-a443-e0be5c9dd479", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "31d9c227-43cc-4154-bef6-180d2153ca0f", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "f7775b8e-d2bf-4eb8-a6bc-293d0b9c3497", "text": "Igaz", "isCorrect": true}, {"id": "cb23496d-b70a-4566-b51f-328a6dad2977", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2e9b450-8313-40b2-bee6-3659fdaba487", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "56647c2d-ae87-455e-8e47-c95a1606dbcf", "text": "Igaz", "isCorrect": true}, {"id": "1b146ba7-35a7-4f7e-bb51-9514c3ce90c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a4256f14-5f77-4793-ac50-d4022940167a", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW()),
('87d35620-7b7c-426d-93a2-a733deff0c12', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b0981598-12d5-495e-95ef-f2d9d193fcd6", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "6aeaf590-758b-46bf-9e7e-1f1dcebb5a8f", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "c7f92079-2d34-4d3e-8e87-c2b114d352a4", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "809f260a-a5ca-4fc5-aa3c-f88826f19e93", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8d6a3201-372b-45fe-a3b9-22338b835ea1", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "a1e8b729-4fd7-41ce-b7fc-d02be26bb9b7", "text": "Igaz", "isCorrect": false}, {"id": "382375e9-3975-4359-846d-30e97d0990a2", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "80f61e73-ddb1-4606-9a52-56f3e50a4be1", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "57e19ac0-ce95-4fe9-925d-4c603a4ebdbb", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "17bc9df3-1fb7-42c2-845a-13d3c11be229", "text": "Igaz", "isCorrect": true}, {"id": "27a3d1e5-31a2-4919-ae15-976ee8884132", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());